function groupedOrders(orders){const groups=[['藥物','Medications'],['檢驗','Laboratory'],['檢查','Examinations'],['處置','Treatment / Care'],['輸血','Transfusion'],['麻醉','Anesthesia'],['會診','Consultations'],['同意書','Consents']];return groups.map(([k,label])=>{const rows=orders.filter(o=>o.type===k).sort((a,b)=>Number(['已停止','已取消'].includes(a.status))-Number(['已停止','已取消'].includes(b.status)));return rows.length?`<section><h3 class="order-group">${e(k)} · ${e(label)} <span class="small muted">${rows.length} 筆</span></h3>${rows.map(orderCard).join('')}</section>`:''}).join('')||'<div class="empty">尚無醫囑</div>'}

function careReviewMarkup(o){if(!o.careReview)return '';const r=o.careReview;return '<br><strong>臨床條件檢核：</strong>'+e([...(r.missing||[]),...(r.warnings||[])].map(clinicalTextZh).join('；')||'已記錄有限範圍檢核')+(r.rationale?'<br>臨床原因： '+e(r.rationale):'')+(r.status==='待確認'?'<br><strong>待開立／照護醫師補齊臨床資料並重新簽署，不得執行。</strong>':'')}

function isCurrentOrder(o){return !['已停止','已取消','已完成','已執行','已給藥','已審核','已回覆','已退藥','已退血','已領用'].includes(o.status)}
function matchesOrderFilter(o){return orderFilter==='all'||orderFilter==='current'&&isCurrentOrder(o)||orderFilter==='pharmacy'&&['待藥師安全確認','待審方'].includes(o.status)||orderFilter==='pending'&&['待確認','待補資料'].includes(o.status)||orderFilter==='clinical'&&MedSafety.active(o)&&ClinicalReconciliation.findings(pNow(),o,state).length>0}
function openMetric(key){if(key==='patients'){patientScope='all';render();dialog('住院病人',patientPicker(),null);return}if(key==='review'){dialog('待覆核工作',reviewView(),null);return}if(!pNow()){dialog('尚未選擇病人','<p>請先從病人清單選擇病人。</p>',null);return}if(key==='orders'){resetOrderList();orderFilter='current';tab='orders'}if(key==='consents'){consentFilter='pending';tab='consents'}render()}

function clinicalTextZh(text){const map={'Diagnosis not documented':'尚未記錄診斷','Documented patient age':'尚缺可查核年齡','Pregnancy/postpartum status':'尚未確認妊娠／產後狀態','Current body weight':'尚缺本次體重','Documented safe swallow screen before any oral intake':'口服前須完成安全吞嚥評估','Individualized fever escalation threshold':'尚缺個別發燒通報界線','Contrast assessment: renal function and pregnancy status':'顯影劑評估尚缺腎功能或妊娠狀態','Radiology contrast safety review pending':'尚待影像醫學端完成顯影劑安全評估','The current diagnosis does not establish the usual indication for this order.':'目前診斷未能確認此醫囑的常見適應症','Pediatric template selected for a patient aged 18 or older.':'已滿18歲病人選用了兒科套組，請核對','Document the clinical question/indication for the examination.':'請記錄檢查目的及欲釐清的問題'};const fields={weightKg:'體重',pregnancy:'妊娠狀態',renal:'腎功能',hepatic:'肝功能',swallow:'吞嚥功能',mobility:'活動限制',careInstruction:'個別照護指示',gestationWeeks:'妊娠週數',acuteStroke:'急性中風狀態'};if(text.startsWith('Required assessment: '))return '尚需評估：'+(fields[text.slice(21)]||text.slice(21));return map[text]||text}
